  'search-heading' => 'Որոնում և առբերում',
  'search-p1' => 'Ստեղծեք ամբողջական տեքստի որոնելի արխիվներ: Փաստաթղթի բովանդակության ինդեքսավորումը հնարավորություն է տալիս գտնել փաստաթղթերը ըստ բովանդակության, ոչ միայն ֆայլի անվանման:',
  'search-p2' => 'Տրամադրեք որոնման բազմաթիվ մեթոդներ: Ամբողջ տեքստի որոնումը, մետատվյալների որոնումը և գրացուցակի զննումը հնարավորություն են տալիս հայտնաբերման տարբեր մոտեցումներ:',
  'search-p3' => 'Թեստի որոնման ընթացակարգեր. Արխիվացումն անարժեք է, եթե փաստաթղթերը հեշտությամբ չեն կարող հետ բերել: Փորձեք, որ արխիվացված փաստաթղթերը կարող են տեղակայվել և բացվել:',
  'search-p4' => 'Փաստաթղթերի որոնման ընթացակարգեր. Արխիվից օգտվողներին անհրաժեշտ են փաստաթղթեր գտնելու և մուտք գործելու հստակ հրահանգներ:',
  'search-p5' => 'Վերահսկել որոնման հարցումները: Հաճախ օգտագործվող փաստաթղթերը կարող են տեղափոխվել ավելի մատչելի պահեստ:',
  'challenges-heading' => 'Պահպանման մարտահրավերներ',
  'challenges-p1' => 'Ձևաչափի հնացումը ռիսկ է: PDF-ը կայուն է, բայց տեխնոլոգիան զարգանում է: Հնացած ձևաչափերով ստեղծված ֆայլերը կարող են անընթեռնելի դառնալ:',
  'challenges-p2' => 'Անդրադառնալով հնացածությանը պրոակտիվ կերպով: Պարբերաբար տեղափոխեք փաստաթղթերը ընթացիկ ձևաչափերին: PDF տարբերակները մնում են ընթեռնելի, բայց միգրացիան դեպի վերջին PDF տարբերակները բարելավում է համատեղելիությունը:',
  'challenges-p3' => 'Պահպանման մեդիայի հնացում: Հին կրիչներում պահվող տվյալները կարող են անհասանելի դառնալ, քանի որ կրիչները հնանում են:',
  'challenges-p4' => 'Փաստաթղթի ձևաչափը փոխվում է: PDF բնութագրերի թարմացումները կարող են հին PDF-ները անհամատեղելի դարձնել նոր ընթերցողների հետ:',
  'challenges-p5' => 'Մետատվյալների կորուստ. Մետատվյալները երբեմն փչացնում են: Կանոնավոր ստուգումը վաղ է բռնում կոռուպցիան:',
  'compliance-heading' => 'Համապատասխանության նկատառումներ',
  'compliance-p1' => 'Առողջապահական կազմակերպությունները պետք է համապատասխանեն HIPAA-ին: Փաստաթղթերը պետք է ապահով լինեն, մուտքը պետք է գրանցվի, և HIPAA-ի կողմից սահմանված պահպանման ժամկետները պետք է պահպանվեն:',
  'compliance-p2' => 'Ֆինանսական ծառայություններ մատուցող կազմակերպությունները պետք է համապատասխանեն SEC-ին և այլ կանոնակարգերին, որոնք նշում են պահպանման ժամկետները: Պահանջվող փաստաթղթերը չպահպանելը պատասխանատվություն է առաջացնում:',
  'compliance-p3' => 'Դատական ​​փաստաթղթերը կառավարող իրավաբանական կազմակերպությունները պետք է ապահովեն փաստաթղթերի պատշաճ պահպանումը: Սփոլիացիայի օրենքներն արգելում են ոչնչացնել համապատասխան փաստաթղթերը:',
  'compliance-p4' => 'Հասկացեք ձեր կազմակերպության համար կիրառելի կանոնակարգերը: Տարբեր արդյունաբերություններ ունեն պահպանման տարբեր պահանջներ:',
  'cost-heading' => 'Ծախսերի կառավարում',
  'cost-p1' => 'Փաստաթղթերի մեծ ծավալների արխիվացումը թանկ է: Նվազեցրեք ծախսերը սեղմման և կրկնօրինակման միջոցով:',
  'cost-p2' => 'Սեղմումը նվազեցնում է պահեստավորման պահանջները հիսունից յոթանասուն տոկոսով: Սեղմված արխիվների պահպանման արժեքը զգալիորեն ավելի քիչ է:',
  'cost-p3' => 'Deduplication-ը հեռացնում է կրկնօրինակ փաստաթղթերը: Կազմակերպությունները հաճախ արխիվացնում են նույն փաստաթղթի մի քանի օրինակներ: Կրկնօրինակների հեռացումը նվազեցնում է պահեստավորման ծախսերը:',
  'cost-p4' => 'Շերտավոր պահեստավորումը նվազեցնում է ծախսերը: Վերջին փաստաթղթերը թանկարժեք ակտիվ պահեստում: Հին փաստաթղթերը ավելի էժան արխիվային պահեստում:',
  'cost-p5' => 'Հաշվարկել մեկ փաստաթղթի արժեքը: Պահպանման ծախսերը հասկանալը առաջնորդում է արխիվի կառավարման որոշումները:',
  'disaster-heading' => 'Աղետների վերականգնում',
  'disaster-p1' => 'Արխիվային ձախողումը ճգնաժամ է ստեղծում. Աղետների վերականգնման պլան.',
  'disaster-p2' => 'Պահպանեք բազմաթիվ օրինակներ տարբեր վայրերում: Եթե ​​մի տեղ ձախողվի, կրկնօրինակները հասանելի կլինեն:',
  'disaster-p3' => 'Պարբերաբար ստուգեք վերականգնման ընթացակարգերը: Վերականգնման տեսական ծրագրերը, որոնք գործնականում ձախողվում են, արժեք չունեն:',
  'disaster-p4' => 'Փաստաթղթերի վերականգնման ընթացակարգեր. Թիմերին անհրաժեշտ են հստակ հրահանգներ՝ պահուստային արխիվներ մուտք գործելու համար:',
  'disaster-p5' => 'Հաշվարկել վերականգնման ժամանակի նպատակները: Որքա՞ն արագ պետք է վերականգնվեն արխիվները: Սա որոշում է պահեստային ռազմավարությունը:',
  'strategy-heading' => 'Պահպանման երկարաժամկետ ռազմավարություն',
  'strategy-p1' => 'Մշակել պահպանման երկարաժամկետ ռազմավարություն: Այս ռազմավարությունը պետք է անդրադառնա ձևաչափի պահպանմանը, լրատվամիջոցների հնացմանը, մետատվյալների պահպանմանը և հասանելիության շարունակականությանը:',
  'strategy-p2' => 'Սահմանել պահպանման քաղաքականություն: Սահմանեք պահպանման ժամկետները, մուտքի վերահսկումը և արխիվային ընթացակարգերը:',
  'strategy-p3' => 'Արխիվային գործունեության բյուջե. Արխիվացումը գումար է պահանջում: Կազմակերպությունները պետք է բյուջետավորեն ընթացիկ արխիվային ծախսերը:',
  'strategy-p4' => 'Վերապատրաստեք արխիվային անձնակազմին. Հավաքածուներ կառավարող արխիվագետները մասնագիտացված գիտելիքների կարիք ունեն:',
  'strategy-p5' => 'Պահպանեք պահպանման ռազմավարությունը ընթացիկ: Տեխնոլոգիան և կանոնակարգերը զարգանում են: Պարբերաբար թարմացրեք պահպանման ռազմավարությունը:',
  'integration-heading' => 'Ինտեգրում փաստաթղթերի աշխատանքային հոսքերի հետ',
  'integration-p1' => 'Արխիվային համակարգերը պետք է ինտեգրվեն փաստաթղթերի մշակման աշխատանքային հոսքերին: Երբ փաստաթղթերը հասնում են արխիվային տարիքի, դրանք պետք է ավտոմատ կերպով տեղափոխվեն արխիվային պահեստ: __MERGE_LINK__ հարակից արխիվացված փաստաթղթերը կազմակերպված հավաքածուներում բարելավում են արխիվների կազմակերպումը և որոնումը: Վերլուծություն կամ վերափոխում պահանջող արխիվների համար __CONVERT_LINK__ արխիվացված փաստաթղթերը խմբագրելի ձևաչափերով պետք է հնարավոր լինեն՝ առանց արխիվի ամբողջականությունը խախտելու:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-p1' => 'PDF արխիվացումը պահպանում է կազմակերպչական փաստաթղթերը երկարաժամկետ հասանելիության համար: Պատշաճ պատրաստումը, պահպանման համապատասխան լուծումները և հստակ կազմակերպումը ապահովում են արխիվների արժեքավոր պահպանումը:',
  'conclusion-p2' => 'Օգտագործեք PDF/A ձևաչափը երկար պահպանման պահանջներով փաստաթղթերի համար: Սեղմեք փաստաթղթերը՝ պահպանման ծախսերը նվազեցնելու համար: Իրականացնել կազմակերպված պահեստավորում լավ մետատվյալներով:',
  'conclusion-p3' => 'Մեծ արխիվների համար օգտագործեք թվային ակտիվների կառավարման պրոֆեսիոնալ համակարգեր: Այս համակարգերը չափվում են միլիոնավոր փաստաթղթերի վրա՝ միաժամանակ ապահովելով ամուր որոնման և մուտքի վերահսկում:',
  'conclusion-p4' => 'Պարբերաբար փորձարկեք արխիվային և որոնման ընթացակարգերը: Արխիվացումը հաջողվում է միայն այն դեպքում, եթե անհրաժեշտության դեպքում փաստաթղթերը հնարավոր լինի առբերել:',
  'conclusion-p5' => 'Պահպանեք բազմաթիվ օրինակներ տարբեր վայրերում: Ավելորդությունը պաշտպանում է պահեստավորման ձախողումներից և տվյալների կորստից:',
);
